--
-- Table structure for table `train_stops`
--

DROP TABLE IF EXISTS `train_stops`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `train_stops` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `train_number` varchar(50) NOT NULL,
  `sequence_no` int NOT NULL,
  `station_code` varchar(50) DEFAULT NULL,
  `station_name` varchar(255) DEFAULT NULL,
  `arrival_time` varchar(20) DEFAULT NULL,
  `departure_time` varchar(20) DEFAULT NULL,
  `journey_day` int DEFAULT NULL,
  `distance_km` double DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_train_sequence` (`train_number`,`sequence_no`),
  KEY `idx_stop_station` (`station_code`),
  KEY `idx_train_station_sequence` (`train_number`,`station_code`,`sequence_no`),
  CONSTRAINT `fk_stop_train` FOREIGN KEY (`train_number`) REFERENCES `trains` (`train_number`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=779072 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

